<div class="business-page"><div class="business-page-header"><div><p class="eyebrow">Organisatie-intelligence</p><h1>Meldingen</h1><p>Beoordeel verdachte communicatie die medewerkers bewust hebben gemeld.</p></div></div><section class="business-card"><div class="business-table-wrap"><table class="business-table"><thead><tr><th>Datum</th><th>Onderwerp</th><th>Afzender</th><th>Status</th><th>Actie</th></tr></thead><tbody><?php foreach ($reports as $report): ?><tr><td><?= e(format_date($report['created_at'], 'j M Y H:i')) ?></td><td><strong><?= e($report['subject'] ?: 'Geen onderwerp') ?></strong><br><span class="form-help"><?= e($report['description'] ?: '') ?></span></td><td><?= e($report['sender_domain'] ?: 'Onbekend') ?></td><td><span class="tag <?= in_array($report['status'], ['new', 'review'], true) ? 'tag-danger' : 'tag-green' ?>"><?= e(status_label((string) $report['status'])) ?></span></td><td><form method="post" action="<?= e(url('/business/reports/action')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($report['id']) ?>"><select class="form-select" name="status" aria-label="Nieuwe status"><option value="new">Nieuw</option><option value="review">In beoordeling</option><option value="resolved">Opgevolgd</option><option value="dismissed">Geen actie</option></select><button class="button button-small button-navy" type="submit">Opslaan</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php if ($reports === []): ?><div class="business-empty">Nog geen meldingen.</div><?php endif; ?></section></div>
